using System.Text.Json;
namespace LocalChat;
partial class MainWindow {
 Settings CloneSettings()=>JsonSerializer.Deserialize<Settings>(JsonSerializer.Serialize(settings,Disk.Json),Disk.Json)!;
 void OpenModelCatalog(){Post("catalog",new{airModels=AirEntries(),airManagedFilesPresent=AirCatalog.HasFiles(root),models=ModelCatalog.Entries(root,settings.Mode,settings.GgufModel),managedFilesPresent=ModelCatalog.AllEntries(root,settings.Mode,settings.GgufModel).Any(x=>x.HasFiles),activeName=ModelCatalog.Active(root,settings.Mode,settings.GgufModel)?.Name,mode=settings.Mode});}
 async Task ChooseManagedModel(string id){RequireIdle();if(importing)throw new Exception("Дождись импорта репозитория.");if(!ModelCatalog.IsOffered(id))throw new Exception("Выбери модель из каталога.");var spec=ModelCatalog.Get(id);bool installed=ModelCatalog.Installed(root,spec);if(!installed&&!await ConfirmAsync("NORA · скачать модель",$"Скачать {spec.Name}?\n\nМодель: {spec.Bytes/1e9:F2} ГБ. Движки Vulkan/CPU: 52 МБ. CUDA (один раз): 658 МБ.\nНужно около {(spec.Bytes+400_000_000)/1e9:F1} ГБ свободного места.\n\nБесплатно, загрузка с Hugging Face / GitHub. Проверяется SHA-256. После загрузки модель будет выбрана; первый ответ загрузит её в память.\n\nОстальные модели и чаты останутся."))return;
  var previous=CloneSettings();bool committed=false;settingUp=true;setupCancel=new();Post("busy",true);Post("setupModel",spec.Name);Post("setupBusy",true);StopAir();StopServer();var token=setupCancel.Token;var progress=new Progress<string>(text=>{if(!closing&&settingUp&&setupCancel?.Token==token){Post("status",text);Post("setupProgress",text);}});Action<string> report=text=>((IProgress<string>)progress).Report(text);
  try{bool valid=installed&&await Task.Run(()=>ModelCatalog.VerifyInstalled(root,spec,report,token),token);if(installed&&!valid){token.ThrowIfCancellationRequested();if(closing)return;if(!await ConfirmAsync("NORA · восстановление","Проверка файлов не пройдена. Скачать/восстановить модель и движок? Нужна загрузка из интернета."))return;}
   var result=valid?spec.Paths(root):await Task.Run(()=>ModelCatalog.Install(root,spec,report,token),token);token.ThrowIfCancellationRequested();if(closing)return;
   var next=CloneSettings();ModelSelection.Apply(next,spec,result);
   try{next.LlamaServer=await Task.Run(()=>CudaRuntime.Install(root,report,token),token);}catch(OperationCanceledException){throw;}catch(Exception cudaError){report("CUDA не установлен: "+cudaError.Message+" · доступен Vulkan/CPU");}
   settings=next;SaveSettings();committed=true;State();Post("catalogChanged");Post("status",spec.Name+" выбрана · загрузится в память при первом сообщении");Post("toast",spec.Name+" подключена. Чаты и другие модели сохранены.");
  }catch(OperationCanceledException){Post("status","Загрузка/переключение остановлено. Сохранённую часть можно продолжить.");}
  catch(Exception e){Post("toast","Модель не подключена: "+e.Message);Post("status","Прежняя модель осталась выбранной");}
  finally{if(!committed){settings=previous;if(!closing)try{SaveSettings();}catch(Exception e){Post("toast","Не удалось сохранить настройки: "+e.Message);}}settingUp=false;setupCancel.Dispose();setupCancel=null;if(!closing){State();Post("setupBusy",false);Post("busy",false);OpenModelCatalog();}}
 }
 async Task DeleteManagedModels(string? id){RequireIdle();if(importing)throw new Exception("Дождись импорта.");var specs=id==null?ModelCatalog.Models:new[]{ModelCatalog.Get(id)};long bytes=ModelCatalog.UsedBytes(root,specs);var existing=specs.Where(s=>Directory.Exists(s.Home(root))).ToArray();if(existing.Length==0){Post("toast","В каталоге нет файлов для удаления.");return;}string list=string.Join("\n",existing.Select(s=>"• "+s.Name));if(!await ConfirmAsync("NORA · удалить модели",(id==null?"Удалить ВСЕ скачанные через NORA модели?":"Удалить модель?")+"\n\n"+list+$"\n\nБудут удалены веса, движки и частичные загрузки: {bytes/1e9:F2} ГБ. Без корзины.\nЧаты, вложения, AirLLM, LM Studio и файлы вне каталога NORA не затрагиваются. Для возврата потребуется скачать модели заново."))return;
  bool removeActive=settings.Mode==2&&existing.Any(s=>ModelCatalog.ContainsFile(root,s,settings.GgufModel));if(removeActive){var old=CloneSettings();StopServer();settings.GgufModel="";settings.LlamaServer="";settings.CpuFallbackServer="";settings.FastQwenMode=false;try{SaveSettings();}catch{settings=old;throw;}}
  settingUp=true;setupCancel=new();Post("busy",true);Post("status","Удаляю файлы каталога моделей…");try{var errors=await Task.Run(()=>ModelCatalog.Delete(root,existing));if(errors.Length>0)Post("toast","Не всё удалено: "+string.Join("\n",errors));else Post("toast",id==null?"Все модели каталога удалены. Чаты сохранены.":"Модель удалена. Чаты сохранены.");}
  finally{settingUp=false;setupCancel.Dispose();setupCancel=null;if(!closing){State();Post("busy",false);OpenModelCatalog();Post("status",removeActive?"Выбери модель в каталоге":"Готово");}}
 }
 void ChooseExternalEngine(int mode){RequireIdle();if(mode is not (0 or 1))throw new Exception("Некорректный движок");if(mode==0&&(!File.Exists(settings.Python)||!File.Exists(Path.Combine(settings.ModelPath,"config.json")))){Post("modelSettingsRequired",0);return;}if(mode==1&&string.IsNullOrWhiteSpace(settings.ModelId)){Post("modelSettingsRequired",1);return;}StopAir();StopServer();settings.Mode=mode;if(mode==0){settings.ContextTokens=512;settings.MaxTokens=128;settings.Reasoning=false;settings.ResponseMode=0;}SaveSettings();State();Post("catalogChanged");Post("toast",mode==0?"Выбран AirLLM":"Выбран локальный сервер LM Studio");}
}